      <h3 id="tournament-bracket-heading">Bracket</h3>
      {tournament.matches.map((match, index) => (
        <MatchTable key={`${match.round}-${match.matchNumber}`} match={match} index={index} tournament={tournament} />
      ))}
    </section>
