import { useCallback, useImperativeHandle, useLayoutEffect, useMemo, useRef } from 'react';
import { faceUpCards } from '../game.ts';
import { Card } from './Card.tsx';
import { useBoardFocus } from './use-board-focus.ts';
import type { CSSProperties, RefObject } from 'react';
import type { GameState } from '../game.ts';
import './board.css';

interface BoardProps {
  game: GameState;
  ref: RefObject<BoardFocus | null>;
  activate(index: number): void;
  helpId?: string;
  regionLabel?: string;
}
const NEAREST: ScrollIntoViewOptions = { block: 'nearest', inline: 'nearest' };
interface BoardStyle extends CSSProperties {
  '--grid-size': number;
}

export interface BoardFocus {
  focusRemembered(): void;
}

// Once a click or tap completes, the focused card can move fully into view.
function cardClicked(card: HTMLElement): void {
  card.scrollIntoView(NEAREST);
}

export function Board({
  game,
  ref,
  activate,
  helpId = 'board-help',
  regionLabel = 'Game board',
}: BoardProps) {
  const { size, deck, matched, selection } = game;
  const { viewport, element, focused, focusRemembered, navigate, cardFocused } =
    useBoardFocus(size);
  useImperativeHandle(ref, () => ({ focusRemembered }), [focusRemembered]);
  // A clock tick keeps both arrays, so the cards' props stay equal and no card renders again.
  const faceUp = useMemo(() => faceUpCards({ matched, selection }), [matched, selection]);
  const matchedCards = useMemo(() => new Set(matched), [matched]);
  // The game passes a new handler on each render. Cards keep one callback that calls the latest.
  const latestActivate = useRef(activate);
  useLayoutEffect(() => {
    latestActivate.current = activate;
  });
  const activateCard = useCallback((index: number) => latestActivate.current(index), []);
  const style: BoardStyle = { '--grid-size': size };
  return (
    <div
      ref={viewport}
      className="board-viewport"
      role="region"
      aria-label={regionLabel}
      aria-describedby={helpId}
    >
      <div className="board" ref={element} style={style}>
        {deck.map((face, index) => (
          <Card
            key={index}
            index={index}
            size={size}
            face={faceUp.has(index) ? face : null}
            matched={matchedCards.has(index)}
            tabIndex={focused === index ? 0 : -1}
            activate={activateCard}
            focus={cardFocused}
            clicked={cardClicked}
            navigate={navigate}
          />
        ))}
      </div>
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import { TournamentHistory } from './TournamentHistory.tsx';
import { TournamentPlay } from './TournamentPlay.tsx';
import { TournamentSetup } from './TournamentSetup.tsx';
import { TournamentTools } from './TournamentTools.tsx';
import { playerName } from './model.ts';
import { useTournament } from './use-tournament.ts';
import './tournament.css';

interface TournamentProps {
  backToGame(): void;
}

export function Tournament({ backToGame }: TournamentProps) {
  const controller = useTournament();
  const [count, setCount] = useState(4);
  const [names, setNames] = useState<string[]>(Array.from({ length: 8 }, () => ''));
  const [json, setJson] = useState('');
  const [setupNotice, setSetupNotice] = useState('');
  const [setupAnnouncement, setSetupAnnouncement] = useState(0);
  const heading = useRef<HTMLHeadingElement>(null);
  useEffect(() => heading.current?.focus(), []);

  const tournament = controller.tournament;
  const match = tournament?.matches[tournament.currentMatch];
  const player = tournament ? playerName(tournament, match?.playerSeeds[tournament.currentTurn] ?? null) : '';
  const statusText = setupNotice || (tournament?.status === 'finished'
    ? `Champion: ${playerName(tournament, tournament.championSeed)}${controller.feedback ? `. ${controller.feedback}` : ''}${controller.notice ? `. ${controller.notice}` : ''}`
    : controller.notice || (tournament ? `Now playing: ${player}${controller.feedback ? `. ${controller.feedback}` : ''}` : ''));
  const statusKey = `${controller.announcement}-${setupAnnouncement}-${tournament?.currentMatch ?? ''}-${tournament?.currentTurn ?? ''}-${tournament?.status ?? ''}`;

  function updateName(index: number, name: string): void {
    setNames((previous) => previous.map((value, item) => item === index ? name : value));
  }

  function leave(): void {
    controller.discard();
    backToGame();
  }

  return (
    <section className="tournament-screen" aria-labelledby="tournament-heading">
      <h2 id="tournament-heading" ref={heading} tabIndex={-1}>Tournament</h2>
      <p className="intro">Take turns on the same deal. The player with fewer moves advances.</p>
      <div className={`game-result tournament-live-status ${tournament?.status === 'finished' ? 'tournament-live-champion' : ''}`}>
        <p id="tournament-status" role="status" aria-live="polite" aria-atomic="true">
          <span key={statusKey}>{statusText}</span>
        </p>
      </div>
      {controller.tournament ? (
        <TournamentPlay
          tournament={controller.tournament}
          activate={controller.activate}
          startTurn={controller.beginTurn}
          nextTurn={controller.continueTurn}
          nextMatch={controller.continueMatch}
          leave={leave}
          backToGame={backToGame}
        />
      ) : (
        <TournamentSetup
          count={count}
          names={names}
          notice={setupNotice}
          onCount={(value) => { setSetupNotice(''); setCount(value); }}
          onName={(index, name) => { setSetupNotice(''); updateName(index, name); }}
          onNotice={(message) => {
            setSetupNotice(message);
            setSetupAnnouncement((value) => value + 1);
          }}
          onStart={controller.begin}
          backToGame={backToGame}
        />
      )}
      <TournamentTools
        json={json}
        hasNotice={controller.notice !== ''}
        onJson={setJson}
        onExport={() => setJson(controller.exportCurrent(count, names))}
        onLoad={() => {
          setSetupNotice('');
          const loaded = controller.load(json);
          if (loaded?.kind === 'setup') {
            setCount(loaded.count);
            setNames([...loaded.names]);
          }
        }}
      />
      <TournamentHistory
        records={controller.history}
        storageAvailable={controller.storageAvailable}
        onView={controller.viewPast}
      />
    </section>
  );
}
import type { FormEvent } from 'react';
import { acceptedNames, normalizePlayerName } from './model.ts';
import './tournament.css';

interface SetupProps {
  count: number;
  names: readonly string[];
  onCount(count: number): void;
  onName(index: number, name: string): void;
  notice: string;
  onNotice(message: string): void;
  onStart(names: readonly string[]): void;
  backToGame(): void;
}

export function TournamentSetup({ count, names, notice, onCount, onName, onNotice, onStart, backToGame }: SetupProps) {
  function submit(event: FormEvent<HTMLFormElement>): void {
    event.preventDefault();
    const chosen = names.slice(0, count).map(normalizePlayerName);
    if (chosen.some((name) => Array.from(name).length < 2 || Array.from(name).length > 20)) {
      onNotice('Use 2 to 20 characters.');
      return;
    }
    if (new Set(chosen.map((name) => name.toLowerCase())).size !== count) {
      onNotice('Each name must be different.');
      return;
    }
    const accepted = acceptedNames(names, count);
    if (!accepted) return;
    onNotice('');
    onStart(accepted);
  }
  return (
    <section className="tournament-setup" aria-labelledby="tournament-setup-heading">
      <h3 id="tournament-setup-heading">Set up tournament</h3>
      <form onSubmit={submit}>
        <div className="tournament-count">
          <label htmlFor="tournament-player-count">Players</label>
          <select
            id="tournament-player-count"
            className="control"
            value={count}
            onChange={(event) => onCount(Number(event.currentTarget.value))}
          >
            <option value={4}>4</option>
            <option value={8}>8</option>
          </select>
        </div>
        <div className="tournament-players">
          {Array.from({ length: 8 }, (_, index) => (
            <div className="tournament-player-field" key={index}>
              <label htmlFor={`tournament-player-${index + 1}`}>Player {index + 1}</label>
              <input
                id={`tournament-player-${index + 1}`}
                className="control"
                type="text"
                autoComplete="off"
                aria-describedby={notice ? 'tournament-status' : undefined}
                value={names[index] ?? ''}
                disabled={index >= count}
                onChange={(event) => onName(index, event.currentTarget.value)}
              />
            </div>
          ))}
        </div>
        <div className="tournament-actions">
          <button type="submit" className="control">Start tournament</button>
          <button type="button" className="control" onClick={backToGame}>Back to game</button>
        </div>
      </form>
    </section>
  );
}
import { useEffect, useRef } from 'react';
