import {
  hasExactKeys,
  isJsonObject,
  isNonnegativeSafeInteger,
  parseJson,
} from '../saved-format.ts';
import { acceptedNames, normalizePlayerName } from './model.ts';
import type { TournamentPlayer, TournamentRecord, TournamentState } from './model.ts';
import { readTournamentMatches } from './validation-matches.ts';
import { isValidTournamentGame, isValidTournamentProgress } from './validation-progress.ts';

const RECORD_KEYS = ['championSeed', 'currentMatch', 'currentTurn', 'matches', 'players', 'status'];
const STATE_KEYS = ['activeGame', ...RECORD_KEYS];
const SNAPSHOT_KEYS = [
  'boardCode',
  'elapsedMs',
  'matched',
  'moves',
  'selection',
  'started',
  'version',
];

export function findUnknownTournamentField(text: string): string | null {
  if (text.length > 262_144) return null;
  const root = parseJson(text);
  if (!isJsonObject(root)) return null;
  const rootField = unknownField(root, ['format', 'tournament', 'version']);
  if (rootField) return rootField;
  const event = root.tournament;
  if (!isJsonObject(event)) return null;
  const setup = event.kind === 'setup';
  const eventField = unknownField(event, setup ? ['kind', 'names', 'players'] : STATE_KEYS);
  if (eventField) return eventField;
  if (setup) return null;
  if (Array.isArray(event.players)) {
    for (const player of event.players) {
      const field = unknownField(player, ['name', 'seed']);
      if (field) return field;
    }
  }
  if (Array.isArray(event.matches)) {
    for (const match of event.matches) {
      const field = unknownField(match, MATCH_FIELD_NAMES);
      if (field) return field;
      if (isJsonObject(match) && Array.isArray(match.results)) {
        for (const result of match.results) {
          const resultField = unknownField(result, ['elapsedMs', 'moves', 'seed']);
          if (resultField) return resultField;
        }
      }
    }
  }
  if (typeof event.activeGame === 'string') return snapshotUnknownField(event.activeGame);
  return null;
}

function unknownField(value: unknown, allowed: readonly string[]): string | null {
  if (!isJsonObject(value)) return null;
  return Object.keys(value).find((key) => !allowed.includes(key)) ?? null;
}

function snapshotUnknownField(text: string): string | null {
  const snapshot = parseJson(text);
  if (!isJsonObject(snapshot)) return null;
  const field = unknownField(snapshot, SNAPSHOT_KEYS);
  if (field) return field;
  const selection = snapshot.selection;
  if (!isJsonObject(selection)) return null;
  const keys =
    selection.kind === 'mismatch'
      ? ['first', 'kind', 'remainingMs', 'second']
      : selection.kind === 'one'
        ? ['index', 'kind']
        : ['kind'];
  return unknownField(selection, keys);
}

const MATCH_FIELD_NAMES = [
  'boardCode',
  'feeders',
  'matchNumber',
  'playerSeeds',
  'results',
  'round',
  'size',
  'winnerSeed',
];

export function readTournamentRecord(value: unknown): TournamentRecord | null {
  if (!isJsonObject(value) || !hasExactKeys(value, RECORD_KEYS) || value.status !== 'finished')
    return null;
  const state = readTournamentFields(value, null);
  if (!state || state.status !== 'finished' || state.championSeed === null) return null;
  const { status, players, matches, currentMatch, currentTurn, championSeed } = state;
  return { status, players, matches, currentMatch, currentTurn, championSeed };
}

export function readTournamentState(value: unknown): TournamentState | null {
  if (!isJsonObject(value) || !hasExactKeys(value, STATE_KEYS)) return null;
  const gameText = value.activeGame;
  if (gameText !== null && typeof gameText !== 'string') return null;
  const game = typeof gameText === 'string' ? decodeSnapshot(gameText) : null;
  if (typeof gameText === 'string' && !game) return null;
  const state = readTournamentFields(value, game);
  return state && isValidTournamentGame(state) ? state : null;
}

function readTournamentFields(
  value: Record<string, unknown>,
  game: TournamentState['activeGame'],
): TournamentState | null {
  const currentMatch = value.currentMatch;
  const currentTurn = value.currentTurn;
  const status = value.status;
  const championSeed = value.championSeed;
  if (
    !isNonnegativeSafeInteger(currentMatch) ||
    !isNonnegativeSafeInteger(currentTurn) ||
    (currentTurn !== 0 && currentTurn !== 1) ||
    (status !== 'active' && status !== 'finished') ||
    !(championSeed === null || isNonnegativeSafeInteger(championSeed))
  )
    return null;
  const players = readPlayers(value.players);
  if (!players) return null;
  const matches = readTournamentMatches(value.matches, players.length);
  if (
    !matches ||
    !isValidTournamentProgress(
      players.length,
      matches,
      currentMatch,
      currentTurn,
      status,
      championSeed,
    )
  )
    return null;
  return {
    status,
    players,
    matches,
    currentMatch,
    currentTurn,
    activeGame: game,
    turnRunning: false,
    championSeed,
  };
}

function readPlayers(value: unknown): TournamentPlayer[] | null {
  if (!Array.isArray(value) || (value.length !== 4 && value.length !== 8)) return null;
  const players: TournamentPlayer[] = [];
  for (let index = 0; index < value.length; index += 1) {
    const item: unknown = value[index];
    if (!isJsonObject(item) || !hasExactKeys(item, ['name', 'seed'])) return null;
    const nameValue = item.name;
    const seed = item.seed;
    if (typeof nameValue !== 'string' || !isNonnegativeSafeInteger(seed) || seed !== index + 1)
      return null;
    const name = normalizePlayerName(nameValue);
    if (name !== nameValue || !acceptedNames([name], 1)) return null;
    players.push({ name, seed });
  }
  return acceptedNames(
    players.map((player) => player.name),
    players.length,
  )
    ? players
    : null;
}
import { ELAPSED_MAX_MS, MOVES_MAX } from '../game.ts';
import { parseBoardCode } from '../deck.ts';
import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger } from '../saved-format.ts';
import { matchSpecs } from './bracket.ts';
import type { TournamentMatch, TournamentResult, TournamentRound } from './model.ts';
import { compareTournamentResults } from './rules.ts';

const MATCH_KEYS = [
  'boardCode',
  'feeders',
  'matchNumber',
  'playerSeeds',
  'results',
  'round',
  'size',
  'winnerSeed',
];

export function readTournamentMatches(
  value: unknown,
  playerCount: number,
): TournamentMatch[] | null {
  const specs = matchSpecs(playerCount);
  if (!Array.isArray(value) || value.length !== specs.length) return null;
  const matches: TournamentMatch[] = [];
  const codes = new Set<string>();
  for (let index = 0; index < value.length; index += 1) {
    const item: unknown = value[index];
    const spec = specs[index];
    if (!spec || !isJsonObject(item) || !hasExactKeys(item, MATCH_KEYS)) return null;
    const boardCode = item.boardCode;
    if (
      typeof boardCode !== 'string' ||
      parseBoardCode(boardCode)?.size !== spec.size ||
      codes.has(boardCode) ||
      !isRound(item.round) ||
      item.round !== spec.round ||
      item.matchNumber !== spec.matchNumber ||
      item.size !== spec.size
    )
      return null;
    const playerSeeds = readSeeds(item.playerSeeds, playerCount);
    const feeders = readFeeders(item.feeders, specs.length);
    const results = readResults(item.results, playerSeeds, spec.size);
    if (!playerSeeds || !sameFeeders(feeders, spec.feeders) || !results) return null;
    if (!(item.winnerSeed === null || isNonnegativeSafeInteger(item.winnerSeed))) return null;
    const winner =
      results[0] && results[1] ? compareTournamentResults(results[0], results[1]) : null;
    if (item.winnerSeed !== winner) return null;
    codes.add(boardCode);
    matches.push({
      boardCode,
      feeders,
      matchNumber: spec.matchNumber,
      playerSeeds,
      results,
      round: spec.round,
      size: spec.size,
      winnerSeed: winner,
    });
  }
  return matches;
}

function readSeeds(value: unknown, count: number): readonly [number | null, number | null] | null {
  if (!Array.isArray(value) || value.length !== 2) return null;
  const first: unknown = value[0];
  const second: unknown = value[1];
  const valid = (seed: unknown): seed is number | null =>
    seed === null || (isNonnegativeSafeInteger(seed) && seed > 0 && seed <= count);
  return valid(first) && valid(second) ? [first, second] : null;
}

function readFeeders(value: unknown, count: number): readonly [number, number] | null | false {
  if (value === null) return null;
  if (!Array.isArray(value) || value.length !== 2) return false;
  const first: unknown = value[0];
  const second: unknown = value[1];
  if (!isNonnegativeSafeInteger(first) || !isNonnegativeSafeInteger(second)) return false;
  if (first >= count || second >= count || first === second) return false;
  return [first, second];
}

function sameFeeders(
  actual: readonly [number, number] | null | false,
  expected: readonly [number, number] | null,
): actual is readonly [number, number] | null {
  return (
    actual !== false &&
    (actual === null
      ? expected === null
      : expected !== null && actual[0] === expected[0] && actual[1] === expected[1])
  );
}

function readResults(
  value: unknown,
  seeds: readonly [number | null, number | null] | null,
  size: number,
): readonly [TournamentResult | null, TournamentResult | null] | null {
  if (!seeds || !Array.isArray(value) || value.length !== 2) return null;
  const first = readResult(value[0], seeds[0], size);
  const second = readResult(value[1], seeds[1], size);
  if (first === false || second === false) return null;
  return [first, second];
}

function readResult(
  value: unknown,
  seed: number | null,
  size: number,
): TournamentResult | null | false {
  if (value === null) return null;
  if (!isJsonObject(value) || !hasExactKeys(value, ['elapsedMs', 'moves', 'seed'])) return false;
  const moves = value.moves;
  const elapsedMs = value.elapsedMs;
  if (
    seed === null ||
    value.seed !== seed ||
    !isNonnegativeSafeInteger(moves) ||
    moves > MOVES_MAX ||
    moves < size ** 2 / 2 ||
    typeof elapsedMs !== 'number' ||
    !Number.isFinite(elapsedMs) ||
    elapsedMs < 0 ||
    elapsedMs > ELAPSED_MAX_MS
  )
    return false;
  return { elapsedMs, moves, seed };
}

function isRound(value: unknown): value is TournamentRound {
  return value === 'Quarterfinal' || value === 'Semifinal' || value === 'Final';
}
import { isWon } from '../game.ts';
import type { TournamentMatch, TournamentState } from './model.ts';
import { matchSpecs } from './bracket.ts';

export function isValidTournamentProgress(
  count: number,
  matches: readonly TournamentMatch[],
  current: number,
  turn: number,
  status: unknown,
  champion: unknown,
): boolean {
  if (current >= matches.length) return false;
  const specs = matchSpecs(count);
  for (let index = 0; index < matches.length; index += 1) {
    const match = matches[index];
    const spec = specs[index];
    if (!match || !spec) return false;
    if (index < current && match.winnerSeed === null) return false;
    if (index > current && (match.winnerSeed !== null || match.results[0] || match.results[1]))
      return false;
    if (!spec.feeders) {
      if (
        match.playerSeeds[0] !== spec.playerSeeds[0] ||
        match.playerSeeds[1] !== spec.playerSeeds[1]
      )
        return false;
    } else if (index <= current) {
      const first = matches[spec.feeders[0]]?.winnerSeed;
      const second = matches[spec.feeders[1]]?.winnerSeed;
      if (first === null || first === undefined || second === null || second === undefined)
        return false;
      if (match.playerSeeds[0] !== first || match.playerSeeds[1] !== second) return false;
    } else if (match.playerSeeds[0] !== null || match.playerSeeds[1] !== null) return false;
  }
  const activeMatch = matches[current];
  if (
    !activeMatch ||
    (turn === 1 && !activeMatch.results[0]) ||
    (turn === 0 && activeMatch.results[1])
  )
    return false;
  if (status === 'finished') {
    return (
      current === matches.length - 1 &&
      matches.every((match) => match.winnerSeed !== null) &&
      champion === matches.at(-1)?.winnerSeed
    );
  }
  return champion === null && !(current === matches.length - 1 && activeMatch.winnerSeed !== null);
}

export function isValidTournamentGame(state: TournamentState): boolean {
  const game = state.activeGame;
  if (!game) return true;
  const match = state.matches[state.currentMatch];
  return (
    state.status === 'active' &&
    match?.boardCode === game.boardCode &&
    !match.results[state.currentTurn] &&
    !isWon(game)
  );
}
