    synchronize,
    reset: () => {
      clock.current = createClock(performance.now());
    },
    pause: () => {
      synchronize();
      suspended.current = true;
      clock.current = createClock(performance.now());
      setIsSuspended(true);
    },
    resume: () => {
      clock.current = createClock(performance.now());
      suspended.current = false;
      setIsSuspended(false);
    },
  };
}
