const FORMAT = 'neon-pairs/tournament';

export function encodeTournament(state: TournamentState | TournamentRecord): string {
  const candidate = 'activeGame' in state ? state.activeGame : null;
  const activeGame = candidate && !isWon(candidate) ? candidate : null;
  const tournament = {
    activeGame: activeGame ? encodeSnapshot(activeGame) : null,
    championSeed: state.championSeed,
    currentMatch: state.currentMatch,
    currentTurn: state.currentTurn,
    matches: state.matches.map((match) => ({
      boardCode: match.boardCode,
      feeders: match.feeders,
      matchNumber: match.matchNumber,
      playerSeeds: match.playerSeeds,
      results: match.results.map((result) =>
        result ? { elapsedMs: result.elapsedMs, moves: result.moves, seed: result.seed } : null,
      ),
      round: match.round,
      size: match.size,
      winnerSeed: match.winnerSeed,
    })),
    players: state.players.map((player) => ({ name: player.name, seed: player.seed })),
    status: state.status,
  };
  return JSON.stringify({ format: FORMAT, tournament, version: 1 }, null, 2);
}

export function encodeTournamentSetup(count: number, names: readonly string[]): string {
  return JSON.stringify(
    {
      format: FORMAT,
      tournament: { kind: 'setup', names, players: count },
      version: 1,
    },
    null,
    2,
  );
}

export function decodeTournament(text: string): TournamentImport | null {
  if (!isWithinBytes(text, MAX_TOURNAMENT_BYTES)) return null;
  const value = parseJson(text);
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['format', 'tournament', 'version']) ||
    value.format !== FORMAT ||
    value.version !== 1
  )
    return null;
  if (isJsonObject(value.tournament) && value.tournament.kind === 'setup') {
    const setup = value.tournament;
    if (!hasExactKeys(setup, ['kind', 'names', 'players'])) return null;
    if (
      (setup.players !== 4 && setup.players !== 8) ||
      !Array.isArray(setup.names) ||
      setup.names.length !== 8
    )
      return null;
    const names: string[] = [];
    for (const name of setup.names) {
      if (typeof name !== 'string') return null;
      names.push(name);
    }
    return { kind: 'setup', count: setup.players, names };
  }
  const state = readTournamentState(value.tournament);
  return state ? { kind: 'event', state } : null;
}
import { decodeSnapshot } from '../snapshot.ts';
import {
  hasExactKeys,
  isJsonObject,
  isNonnegativeSafeInteger,
  parseJson,
} from '../saved-format.ts';
import { acceptedNames, normalizePlayerName } from './model.ts';
import type { TournamentPlayer, TournamentRecord, TournamentState } from './model.ts';
import { readTournamentMatches } from './validation-matches.ts';
import { isValidTournamentGame, isValidTournamentProgress } from './validation-progress.ts';

const RECORD_KEYS = ['championSeed', 'currentMatch', 'currentTurn', 'matches', 'players', 'status'];
const STATE_KEYS = ['activeGame', ...RECORD_KEYS];
const SNAPSHOT_KEYS = [
  'boardCode',
  'elapsedMs',
  'matched',
  'moves',
  'selection',
  'started',
  'version',
];

export function findUnknownTournamentField(text: string): string | null {
  if (text.length > 262_144) return null;
  const root = parseJson(text);
  if (!isJsonObject(root)) return null;
  const rootField = unknownField(root, ['format', 'tournament', 'version']);
  if (rootField) return rootField;
  const event = root.tournament;
  if (!isJsonObject(event)) return null;
  const setup = event.kind === 'setup';
  const eventField = unknownField(event, setup ? ['kind', 'names', 'players'] : STATE_KEYS);
  if (eventField) return eventField;
  if (setup) return null;
  if (Array.isArray(event.players)) {
    for (const player of event.players) {
      const field = unknownField(player, ['name', 'seed']);
      if (field) return field;
    }
  }
  if (Array.isArray(event.matches)) {
    for (const match of event.matches) {
      const field = unknownField(match, MATCH_FIELD_NAMES);
      if (field) return field;
      if (isJsonObject(match) && Array.isArray(match.results)) {
        for (const result of match.results) {
          const resultField = unknownField(result, ['elapsedMs', 'moves', 'seed']);
          if (resultField) return resultField;
        }
      }
    }
  }
  if (typeof event.activeGame === 'string') return snapshotUnknownField(event.activeGame);
  return null;
}

function unknownField(value: unknown, allowed: readonly string[]): string | null {
  if (!isJsonObject(value)) return null;
  return Object.keys(value).find((key) => !allowed.includes(key)) ?? null;
}

function snapshotUnknownField(text: string): string | null {
  const snapshot = parseJson(text);
  if (!isJsonObject(snapshot)) return null;
  const field = unknownField(snapshot, SNAPSHOT_KEYS);
  if (field) return field;
  const selection = snapshot.selection;
  if (!isJsonObject(selection)) return null;
  const keys =
    selection.kind === 'mismatch'
      ? ['first', 'kind', 'remainingMs', 'second']
      : selection.kind === 'one'
        ? ['index', 'kind']
        : ['kind'];
  return unknownField(selection, keys);
}

const MATCH_FIELD_NAMES = [
  'boardCode',
  'feeders',
  'matchNumber',
  'playerSeeds',
  'results',
  'round',
  'size',
  'winnerSeed',
];

export function readTournamentRecord(value: unknown): TournamentRecord | null {
  if (!isJsonObject(value) || !hasExactKeys(value, RECORD_KEYS) || value.status !== 'finished')
    return null;
  const state = readTournamentFields(value, null);
  if (!state || state.status !== 'finished' || state.championSeed === null) return null;
  const { status, players, matches, currentMatch, currentTurn, championSeed } = state;
  return { status, players, matches, currentMatch, currentTurn, championSeed };
}

export function readTournamentState(value: unknown): TournamentState | null {
  if (!isJsonObject(value) || !hasExactKeys(value, STATE_KEYS)) return null;
  const gameText = value.activeGame;
  if (gameText !== null && typeof gameText !== 'string') return null;
  const game = typeof gameText === 'string' ? decodeSnapshot(gameText) : null;
  if (typeof gameText === 'string' && !game) return null;
  const state = readTournamentFields(value, game);
  return state && isValidTournamentGame(state) ? state : null;
}

function readTournamentFields(
  value: Record<string, unknown>,
  game: TournamentState['activeGame'],
): TournamentState | null {
  const currentMatch = value.currentMatch;
  const currentTurn = value.currentTurn;
  const status = value.status;
  const championSeed = value.championSeed;
  if (
    !isNonnegativeSafeInteger(currentMatch) ||
    !isNonnegativeSafeInteger(currentTurn) ||
    (currentTurn !== 0 && currentTurn !== 1) ||
    (status !== 'active' && status !== 'finished') ||
    !(championSeed === null || isNonnegativeSafeInteger(championSeed))
  )
    return null;
  const players = readPlayers(value.players);
  if (!players) return null;
  const matches = readTournamentMatches(value.matches, players.length);
  if (
    !matches ||
    !isValidTournamentProgress(
      players.length,
      matches,
      currentMatch,
      currentTurn,
      status,
      championSeed,
    )
  )
    return null;
  return {
    status,
    players,
    matches,
    currentMatch,
    currentTurn,
    activeGame: game,
    turnRunning: false,
    championSeed,
  };
}

function readPlayers(value: unknown): TournamentPlayer[] | null {
  if (!Array.isArray(value) || (value.length !== 4 && value.length !== 8)) return null;
  const players: TournamentPlayer[] = [];
  for (let index = 0; index < value.length; index += 1) {
    const item: unknown = value[index];
    if (!isJsonObject(item) || !hasExactKeys(item, ['name', 'seed'])) return null;
    const nameValue = item.name;
    const seed = item.seed;
    if (typeof nameValue !== 'string' || !isNonnegativeSafeInteger(seed) || seed !== index + 1)
      return null;
    const name = normalizePlayerName(nameValue);
    if (name !== nameValue || !acceptedNames([name], 1)) return null;
    players.push({ name, seed });
  }
  return acceptedNames(
    players.map((player) => player.name),
    players.length,
  )
    ? players
    : null;
}

import { activateCard, advanceGame, createGame, isWon } from '../game.ts';
import type { GameState } from '../game.ts';
import { feedMatch, makeMatches } from './bracket.ts';
import type { MatchSpec } from './bracket.ts';
import type {
  TournamentMatch,
  TournamentPlayer,
  TournamentResult,
  TournamentState,
} from './model.ts';

export function createTournament(
  names: readonly string[],
  specs: readonly MatchSpec[],
  codes: readonly string[],
): TournamentState {
  const players: TournamentPlayer[] = names.map((name, index) => ({ name, seed: index + 1 }));
  const matches = makeMatches(specs, codes);
  return {
    status: 'active',
    players,
    matches,
    currentMatch: 0,
    currentTurn: 0,
    activeGame: null,
    turnRunning: false,
    championSeed: null,
  };
}

export function startTurn(state: TournamentState): TournamentState {
  const match = state.matches[state.currentMatch];
  if (state.status !== 'active' || !match || match.results[state.currentTurn]) return state;
  const game = state.activeGame ?? createGame(match.boardCode);
  if (isWon(game)) return state;
  return { ...state, activeGame: game, turnRunning: true };
}

export function advanceTournamentGame(
  state: TournamentState,
  milliseconds: number,
): TournamentState {
  if (!state.turnRunning || !state.activeGame) return state;
  const game = advanceGame(state.activeGame, milliseconds);
  return game === state.activeGame ? state : { ...state, activeGame: game };
}

export function activateTournamentCard(state: TournamentState, index: number): TournamentState {
  if (!state.turnRunning || !state.activeGame || isWon(state.activeGame)) return state;
  const game = activateCard(state.activeGame, index);
  return game === state.activeGame
    ? state
    : completeTurnIfWon({ ...state, activeGame: game }, game);
}

function completeTurnIfWon(state: TournamentState, game: GameState): TournamentState {
  if (!isWon(game)) return state;
  const match = state.matches[state.currentMatch];
  const seed = match?.playerSeeds[state.currentTurn];
  if (!match || seed === null || seed === undefined) return state;
  const result: TournamentResult = { seed, moves: game.moves, elapsedMs: game.elapsedMs };
  const results: [TournamentResult | null, TournamentResult | null] = [
    match.results[0],
    match.results[1],
  ];
  results[state.currentTurn] = result;
  const winnerSeed =
    results[0] && results[1] ? compareTournamentResults(results[0], results[1]) : null;
  const updated: TournamentMatch = { ...match, results, winnerSeed };
  const matches = state.matches.map((item, index) =>
    index === state.currentMatch ? updated : item,
  );
  const isFinal = state.currentMatch === matches.length - 1;
  return {
    ...state,
    matches,
    turnRunning: false,
    status: isFinal && winnerSeed !== null ? 'finished' : 'active',
    championSeed: isFinal ? winnerSeed : null,
  };
}

export function compareTournamentResults(
  first: TournamentResult,
  second: TournamentResult,
): number {
  if (first.moves !== second.moves) return first.moves < second.moves ? first.seed : second.seed;
  if (first.elapsedMs !== second.elapsedMs)
    return first.elapsedMs < second.elapsedMs ? first.seed : second.seed;
  return Math.min(first.seed, second.seed);
}

export function nextTurn(state: TournamentState): TournamentState {
  const match = state.matches[state.currentMatch];
  if (state.currentTurn !== 0 || !match?.results[0]) return state;
  return { ...state, currentTurn: 1, activeGame: null, turnRunning: false };
}

export function nextMatch(state: TournamentState): TournamentState {
  const match = state.matches[state.currentMatch];
  const index = state.currentMatch + 1;
  if (state.status !== 'active' || !match?.winnerSeed || index >= state.matches.length)
    return state;
  const advanced = feedMatch(state, index);
  return { ...advanced, currentMatch: index, currentTurn: 0, activeGame: null, turnRunning: false };
}
import type { TournamentMatch, TournamentRound, TournamentState } from './model.ts';

export interface MatchSpec {
  readonly round: TournamentRound;
  readonly matchNumber: number;
  readonly size: number;
  readonly playerSeeds: readonly [number | null, number | null];
  readonly feeders: readonly [number, number] | null;
}

export function matchSpecs(count: number): MatchSpec[] {
  const opening: readonly (readonly [number, number])[] =
    count === 4
      ? [
          [1, 4],
          [2, 3],
        ]
      : [
          [1, 8],
          [4, 5],
          [3, 6],
          [2, 7],
        ];
  const round: TournamentRound = count === 4 ? 'Semifinal' : 'Quarterfinal';
  const openingSize = count === 4 ? 6 : 4;
  const specs: MatchSpec[] = opening.map((pair, index) => ({
    round,
    matchNumber: index + 1,
    size: openingSize,
    playerSeeds: pair,
    feeders: null,
  }));
  if (count === 4) {
    specs.push({
      round: 'Final',
      matchNumber: 1,
      size: 8,
      playerSeeds: [null, null],
      feeders: [0, 1],
    });
  } else {
    specs.push(
      { round: 'Semifinal', matchNumber: 1, size: 6, playerSeeds: [null, null], feeders: [0, 1] },
      { round: 'Semifinal', matchNumber: 2, size: 6, playerSeeds: [null, null], feeders: [2, 3] },
      { round: 'Final', matchNumber: 1, size: 8, playerSeeds: [null, null], feeders: [4, 5] },
    );
  }
  return specs;
}

export function makeMatches(
  specs: readonly MatchSpec[],
  codes: readonly string[],
): TournamentMatch[] {
  return specs.map((spec, index): TournamentMatch => ({
    ...spec,
    boardCode: codes[index] ?? '',
    results: [null, null],
    winnerSeed: null,
  }));
}

export function feedMatch(state: TournamentState, index: number): TournamentState {
  const match = state.matches[index];
  if (!match || !match.feeders) return state;
  const first = state.matches[match.feeders[0]]?.winnerSeed;
  const second = state.matches[match.feeders[1]]?.winnerSeed;
  if (first === undefined || first === null || second === undefined || second === null)
    return state;
  const playerSeeds: readonly [number, number] = [first, second];
  const matches = state.matches.map((item, itemIndex) =>
    itemIndex === index ? { ...item, playerSeeds } : item,
  );
  return { ...state, matches };
}
import type { GameState } from '../game.ts';

export type TournamentRound = 'Quarterfinal' | 'Semifinal' | 'Final';
export interface TournamentPlayer {
  readonly name: string;
  readonly seed: number;
}
export interface TournamentResult {
  readonly seed: number;
  readonly moves: number;
  readonly elapsedMs: number;
}
export interface TournamentMatch {
  readonly round: TournamentRound;
  readonly matchNumber: number;
  readonly size: number;
  readonly boardCode: string;
  readonly playerSeeds: readonly [number | null, number | null];
  readonly feeders: readonly [number, number] | null;
  readonly results: readonly [TournamentResult | null, TournamentResult | null];
  readonly winnerSeed: number | null;
}
export interface TournamentState {
  readonly status: 'active' | 'finished';
  readonly players: readonly TournamentPlayer[];
  readonly matches: readonly TournamentMatch[];
  readonly currentMatch: number;
  readonly currentTurn: 0 | 1;
  readonly activeGame: GameState | null;
  readonly turnRunning: boolean;
  readonly championSeed: number | null;
}
export interface TournamentRecord {
  readonly status: 'finished';
  readonly players: readonly TournamentPlayer[];
  readonly matches: readonly TournamentMatch[];
  readonly currentMatch: number;
  readonly currentTurn: 0 | 1;
  readonly championSeed: number;
}
export type TournamentImport =
  | { readonly kind: 'event'; readonly state: TournamentState }
  | { readonly kind: 'setup'; readonly count: number; readonly names: readonly string[] };

export function normalizePlayerName(draft: string): string {
  return draft.trim().replace(/\s+/gu, ' ').normalize('NFC');
}

export function acceptedNames(drafts: readonly string[], count: number): string[] | null {
  const names = drafts.slice(0, count).map(normalizePlayerName);
  if (
    names.some((name) => {
      const length = Array.from(name).length;
      return length < 2 || length > 20;
    })
  )
    return null;
  const keys = names.map((name) => name.toLowerCase());
  return new Set(keys).size === count ? names : null;
}

export function recordOf(state: TournamentState): TournamentRecord | null {
  if (state.status !== 'finished' || state.championSeed === null) return null;
  const { status, players, matches, currentMatch, currentTurn, championSeed } = state;
  return { status, players, matches, currentMatch, currentTurn, championSeed };
}

export function playerName(state: Pick<TournamentState, 'players'>, seed: number | null): string {
  return state.players.find((player) => player.seed === seed)?.name ?? 'TBD';
}

import { useEffect, useRef } from 'react';
import { Board } from '../board/Board.tsx';
import type { BoardFocus } from '../board/Board.tsx';
import { formatElapsed } from '../elapsed-time.ts';
import type { TournamentState } from './model.ts';
import { TournamentBracket } from './TournamentBracket.tsx';
import './tournament.css';

interface TournamentPlayProps {
  tournament: TournamentState;
  activate(index: number): void;
  startTurn(): void;
  nextTurn(): void;
  nextMatch(): void;
  leave(): void;
  backToGame(): void;
}

export function TournamentPlay(props: TournamentPlayProps) {
  const { tournament } = props;
  const match = tournament.matches[tournament.currentMatch];
  const game = tournament.activeGame;
  const currentResult = match?.results[tournament.currentTurn] ?? null;
  const board = useRef<BoardFocus>(null);
  const startButton = useRef<HTMLButtonElement>(null);
  const nextButton = useRef<HTMLButtonElement>(null);
  const backButton = useRef<HTMLButtonElement>(null);
  const hasGame = game !== null;

  useEffect(() => {
    if (tournament.status === 'finished') backButton.current?.focus();
    else if (currentResult) nextButton.current?.focus();
    else if (tournament.turnRunning && hasGame) board.current?.focusRemembered();
    else startButton.current?.focus();
  }, [
    tournament.currentMatch,
    tournament.currentTurn,
    tournament.turnRunning,
    hasGame,
    currentResult,
    tournament.status,
  ]);

  if (!match) return null;
  const canAdvanceMatch = tournament.currentMatch < tournament.matches.length - 1;
  return (
    <section className="tournament-play" aria-labelledby="tournament-play-heading">
      <h3 id="tournament-play-heading">Tournament bracket</h3>
      {game && <GameStatistics game={game} />}
      {game && (
        <>
          <p id="tournament-board-help" className="help">
            Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space
            reveals a card.
          </p>
          <Board
            key={`${tournament.currentMatch}-${tournament.currentTurn}`}
            ref={board}
            game={game}
            activate={props.activate}
            helpId="tournament-board-help"
            regionLabel="Tournament game board"
          />
        </>
      )}
      <div className="tournament-actions">
        {tournament.status === 'active' && !currentResult && (
          <button ref={startButton} type="button" className="control" onClick={props.startTurn}>
            Start turn
          </button>
        )}
        {tournament.status === 'active' && currentResult && tournament.currentTurn === 0 && (
          <button ref={nextButton} type="button" className="control" onClick={props.nextTurn}>
            Next turn
          </button>
        )}
        {tournament.status === 'active' &&
          currentResult &&
          tournament.currentTurn === 1 &&
          canAdvanceMatch && (
            <button ref={nextButton} type="button" className="control" onClick={props.nextMatch}>
              Next match
            </button>
          )}
        {tournament.status === 'active' && (
          <button type="button" className="control" onClick={props.leave}>
            Leave tournament
          </button>
        )}
        {tournament.status === 'finished' && (
          <button ref={backButton} type="button" className="control" onClick={props.backToGame}>
            Back to game
          </button>
        )}
      </div>
      <TournamentBracket tournament={tournament} />
    </section>
  );
}

function GameStatistics({ game }: { game: NonNullable<TournamentState['activeGame']> }) {
  return (
    <dl className="stats tournament-stats">
      <div>
        <dt>Moves:</dt> <dd>{game.moves}</dd>
      </div>
      <div>
        <dt>Pairs:</dt>{' '}
        <dd>
          {game.matched.length / 2}/{game.deck.length / 2}
        </dd>
      </div>
      <div>
        <dt>Time:</dt> <dd>{formatElapsed(game.elapsedMs)}</dd>
      </div>
    </dl>
  );
}
import type { FormEvent } from 'react';
import { acceptedNames, normalizePlayerName } from './model.ts';
import './tournament.css';

interface SetupProps {
  count: number;
  names: readonly string[];
  onCount(count: number): void;
  onName(index: number, name: string): void;
  notice: string;
  onNotice(message: string): void;
  onStart(names: readonly string[]): void;
  backToGame(): void;
}

export function TournamentSetup({
  count,
  names,
  notice,
  onCount,
  onName,
  onNotice,
  onStart,
  backToGame,
}: SetupProps) {
  function submit(event: FormEvent<HTMLFormElement>): void {
    event.preventDefault();
    const chosen = names.slice(0, count).map(normalizePlayerName);
    if (chosen.some((name) => Array.from(name).length < 2 || Array.from(name).length > 20)) {
      onNotice('Use 2 to 20 characters.');
      return;
    }
    if (new Set(chosen.map((name) => name.toLowerCase())).size !== count) {
      onNotice('Each name must be different.');
      return;
    }
    const accepted = acceptedNames(names, count);
    if (!accepted) return;
    onNotice('');
    onStart(accepted);
  }
  return (
    <section className="tournament-setup" aria-labelledby="tournament-setup-heading">
      <h3 id="tournament-setup-heading">Set up tournament</h3>
      <form onSubmit={submit}>
        <div className="tournament-count">
          <label htmlFor="tournament-player-count">Players</label>
          <select
            id="tournament-player-count"
            className="control"
            value={count}
            onChange={(event) => onCount(Number(event.currentTarget.value))}
          >
            <option value={4}>4</option>
            <option value={8}>8</option>
          </select>
        </div>
        <div className="tournament-players">
          {Array.from({ length: 8 }, (_, index) => (
            <div className="tournament-player-field" key={index}>
              <label htmlFor={`tournament-player-${index + 1}`}>Player {index + 1}</label>
              <input
                id={`tournament-player-${index + 1}`}
                className="control"
                type="text"
                autoComplete="off"
                aria-describedby={notice ? 'tournament-status' : undefined}
                value={names[index] ?? ''}
                disabled={index >= count}
                onChange={(event) => onName(index, event.currentTarget.value)}
              />
            </div>
          ))}
        </div>
        <div className="tournament-actions">
          <button type="submit" className="control">
            Start tournament
          </button>
          <button type="button" className="control" onClick={backToGame}>
            Back to game
          </button>
        </div>
      </form>
    </section>
  );
}
