import { parseBoardCode } from '../deck.ts';
import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger } from '../saved-format.ts';
import { matchSpecs } from './bracket.ts';
import type { TournamentMatch, TournamentResult, TournamentRound } from './model.ts';
import { compareTournamentResults } from './rules.ts';

const MATCH_KEYS = [
  'boardCode',
  'feeders',
  'matchNumber',
  'playerSeeds',
  'results',
  'round',
  'size',
  'winnerSeed',
];

export function readTournamentMatches(
  value: unknown,
  playerCount: number,
): TournamentMatch[] | null {
  const specs = matchSpecs(playerCount);
  if (!Array.isArray(value) || value.length !== specs.length) return null;
  const matches: TournamentMatch[] = [];
  const codes = new Set<string>();
  for (let index = 0; index < value.length; index += 1) {
    const item: unknown = value[index];
    const spec = specs[index];
    if (!spec || !isJsonObject(item) || !hasExactKeys(item, MATCH_KEYS)) return null;
    const boardCode = item.boardCode;
    if (
      typeof boardCode !== 'string' ||
      parseBoardCode(boardCode)?.size !== spec.size ||
      codes.has(boardCode) ||
      !isRound(item.round) ||
      item.round !== spec.round ||
      item.matchNumber !== spec.matchNumber ||
      item.size !== spec.size
    )
      return null;
    const playerSeeds = readSeeds(item.playerSeeds, playerCount);
    const feeders = readFeeders(item.feeders, specs.length);
    const results = readResults(item.results, playerSeeds, spec.size);
    if (!playerSeeds || !sameFeeders(feeders, spec.feeders) || !results) return null;
    if (!(item.winnerSeed === null || isNonnegativeSafeInteger(item.winnerSeed))) return null;
    const winner =
      results[0] && results[1] ? compareTournamentResults(results[0], results[1]) : null;
    if (item.winnerSeed !== winner) return null;
    codes.add(boardCode);
    matches.push({
      boardCode,
      feeders,
      matchNumber: spec.matchNumber,
      playerSeeds,
      results,
      round: spec.round,
      size: spec.size,
      winnerSeed: winner,
    });
  }
  return matches;
}

function readSeeds(value: unknown, count: number): readonly [number | null, number | null] | null {
  if (!Array.isArray(value) || value.length !== 2) return null;
  const first: unknown = value[0];
  const second: unknown = value[1];
  const valid = (seed: unknown): seed is number | null =>
    seed === null || (isNonnegativeSafeInteger(seed) && seed > 0 && seed <= count);
  return valid(first) && valid(second) ? [first, second] : null;
}

function readFeeders(value: unknown, count: number): readonly [number, number] | null | false {
  if (value === null) return null;
  if (!Array.isArray(value) || value.length !== 2) return false;
  const first: unknown = value[0];
  const second: unknown = value[1];
  if (!isNonnegativeSafeInteger(first) || !isNonnegativeSafeInteger(second)) return false;
  if (first >= count || second >= count || first === second) return false;
  return [first, second];
}

function sameFeeders(
  actual: readonly [number, number] | null | false,
  expected: readonly [number, number] | null,
): actual is readonly [number, number] | null {
  return (
    actual !== false &&
    (actual === null
      ? expected === null
      : expected !== null && actual[0] === expected[0] && actual[1] === expected[1])
  );
}

function readResults(
  value: unknown,
  seeds: readonly [number | null, number | null] | null,
  size: number,
): readonly [TournamentResult | null, TournamentResult | null] | null {
  if (!seeds || !Array.isArray(value) || value.length !== 2) return null;
  const first = readResult(value[0], seeds[0], size);
  const second = readResult(value[1], seeds[1], size);
  if (first === false || second === false) return null;
  return [first, second];
}

function readResult(
  value: unknown,
  seed: number | null,
  size: number,
): TournamentResult | null | false {
  if (value === null) return null;
  if (!isJsonObject(value) || !hasExactKeys(value, ['elapsedMs', 'moves', 'seed'])) return false;
  const moves = value.moves;
  const elapsedMs = value.elapsedMs;
  if (
    seed === null ||
    value.seed !== seed ||
    !isNonnegativeSafeInteger(moves) ||
    moves > MOVES_MAX ||
    moves < size ** 2 / 2 ||
    typeof elapsedMs !== 'number' ||
    !Number.isFinite(elapsedMs) ||
    elapsedMs < 0 ||
    elapsedMs > ELAPSED_MAX_MS
  )
    return false;
  return { elapsedMs, moves, seed };
}

function isRound(value: unknown): value is TournamentRound {
  return value === 'Quarterfinal' || value === 'Semifinal' || value === 'Final';
}

import { isJsonObject, hasExactKeys, isWithinBytes, parseJson } from '../saved-format.ts';
import { encodeTournament } from './format.ts';
import { readTournamentRecord } from './validation.ts';
import type { TournamentRecord } from './model.ts';

const TOURNAMENTS_KEY = 'np3:tournaments';
const ENVELOPE_VERSION = 3;
const MAX_HISTORY = 10;
const MAX_STORAGE_BYTES = 1_048_576;

interface TournamentStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

interface TournamentHistory {
  readonly records: readonly TournamentRecord[];
  readonly available: boolean;
}

export function readTournamentHistory(store: TournamentStore | null): TournamentHistory {
  if (!store) return { records: [], available: false };
  try {
    const text = store.getItem(TOURNAMENTS_KEY);
    if (!text) return { records: [], available: true };
    if (!isWithinBytes(text, MAX_STORAGE_BYTES)) return { records: [], available: true };
    const value = parseJson(text);
    if (
      !isJsonObject(value) ||
      !hasExactKeys(value, ['items', 'v']) ||
      value.v !== ENVELOPE_VERSION ||
      !Array.isArray(value.items)
    )
      return { records: [], available: true };
    const records = value.items.map(readTournamentRecord);
    return records.some((record) => !record)
      ? { records: [], available: true }
      : {
          records: records
            .filter((record): record is TournamentRecord => record !== null)
            .slice(0, MAX_HISTORY),
          available: true,
        };
  } catch {
    return { records: [], available: false };
  }
}

export function saveTournamentHistory(
  store: TournamentStore | null,
  record: TournamentRecord,
  previous: readonly TournamentRecord[],
): TournamentHistory {
  if (!store) return { records: [record, ...previous].slice(0, MAX_HISTORY), available: false };
  const identity = encodeTournament(record);
  const records = [record, ...previous.filter((item) => encodeTournament(item) !== identity)].slice(
    0,
    MAX_HISTORY,
  );
  try {
    store.setItem(TOURNAMENTS_KEY, JSON.stringify({ v: ENVELOPE_VERSION, items: records }));
    return { records, available: true };
  } catch {
    return { records, available: false };
  }
}
import { isJsonObject, hasExactKeys, isWithinBytes, parseJson } from '../saved-format.ts';
import { isWon } from '../game.ts';
import { encodeSnapshot } from '../snapshot.ts';
import { readTournamentState } from './validation.ts';
import type { TournamentImport, TournamentRecord, TournamentState } from './model.ts';

const MAX_TOURNAMENT_BYTES = 262_144;
const FORMAT = 'neon-pairs/tournament';

export function encodeTournament(state: TournamentState | TournamentRecord): string {
  const candidate = 'activeGame' in state ? state.activeGame : null;
  const activeGame = candidate && !isWon(candidate) ? candidate : null;
  const tournament = {
    activeGame: activeGame ? encodeSnapshot(activeGame) : null,
    championSeed: state.championSeed,
    currentMatch: state.currentMatch,
    currentTurn: state.currentTurn,
    matches: state.matches.map((match) => ({
      boardCode: match.boardCode,
      feeders: match.feeders,
      matchNumber: match.matchNumber,
      playerSeeds: match.playerSeeds,
      results: match.results.map((result) =>
        result ? { elapsedMs: result.elapsedMs, moves: result.moves, seed: result.seed } : null,
      ),
      round: match.round,
      size: match.size,
      winnerSeed: match.winnerSeed,
    })),
    players: state.players.map((player) => ({ name: player.name, seed: player.seed })),
    status: state.status,
  };
  return JSON.stringify({ format: FORMAT, tournament, version: 1 }, null, 2);
}

export function encodeTournamentSetup(count: number, names: readonly string[]): string {
  return JSON.stringify(
    {
      format: FORMAT,
      tournament: { kind: 'setup', names, players: count },
      version: 1,
    },
    null,
    2,
  );
}

export function decodeTournament(text: string): TournamentImport | null {
  if (!isWithinBytes(text, MAX_TOURNAMENT_BYTES)) return null;
  const value = parseJson(text);
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['format', 'tournament', 'version']) ||
    value.format !== FORMAT ||
    value.version !== 1
  )
    return null;
  if (isJsonObject(value.tournament) && value.tournament.kind === 'setup') {
    const setup = value.tournament;
    if (!hasExactKeys(setup, ['kind', 'names', 'players'])) return null;
    if (
      (setup.players !== 4 && setup.players !== 8) ||
      !Array.isArray(setup.names) ||
      setup.names.length !== 8
    )
      return null;
    const names: string[] = [];
    for (const name of setup.names) {
      if (typeof name !== 'string') return null;
      names.push(name);
    }
    return { kind: 'setup', count: setup.players, names };
  }
  const state = readTournamentState(value.tournament);
  return state ? { kind: 'event', state } : null;
}
import type { GameState } from '../game.ts';

export type TournamentRound = 'Quarterfinal' | 'Semifinal' | 'Final';
export interface TournamentPlayer {
  readonly name: string;
  readonly seed: number;
}
export interface TournamentResult {
  readonly seed: number;
  readonly moves: number;
  readonly elapsedMs: number;
}
export interface TournamentMatch {
  readonly round: TournamentRound;
  readonly matchNumber: number;
  readonly size: number;
  readonly boardCode: string;
  readonly playerSeeds: readonly [number | null, number | null];
  readonly feeders: readonly [number, number] | null;
  readonly results: readonly [TournamentResult | null, TournamentResult | null];
  readonly winnerSeed: number | null;
}
export interface TournamentState {
  readonly status: 'active' | 'finished';
  readonly players: readonly TournamentPlayer[];
  readonly matches: readonly TournamentMatch[];
  readonly currentMatch: number;
  readonly currentTurn: 0 | 1;
  readonly activeGame: GameState | null;
  readonly turnRunning: boolean;
  readonly championSeed: number | null;
}
export interface TournamentRecord {
  readonly status: 'finished';
  readonly players: readonly TournamentPlayer[];
  readonly matches: readonly TournamentMatch[];
  readonly currentMatch: number;
  readonly currentTurn: 0 | 1;
  readonly championSeed: number;
}
export type TournamentImport =
  | { readonly kind: 'event'; readonly state: TournamentState }
  | { readonly kind: 'setup'; readonly count: number; readonly names: readonly string[] };

export function normalizePlayerName(draft: string): string {
  return draft.trim().replace(/\s+/gu, ' ').normalize('NFC');
}

export function acceptedNames(drafts: readonly string[], count: number): string[] | null {
  const names = drafts.slice(0, count).map(normalizePlayerName);
  if (
    names.some((name) => {
      const length = Array.from(name).length;
      return length < 2 || length > 20;
    })
  )
    return null;
  const keys = names.map((name) => name.toLowerCase());
  return new Set(keys).size === count ? names : null;
}

export function recordOf(state: TournamentState): TournamentRecord | null {
  if (state.status !== 'finished' || state.championSeed === null) return null;
  const { status, players, matches, currentMatch, currentTurn, championSeed } = state;
  return { status, players, matches, currentMatch, currentTurn, championSeed };
}

export function playerName(state: Pick<TournamentState, 'players'>, seed: number | null): string {
  return state.players.find((player) => player.seed === seed)?.name ?? 'TBD';
}

