import { useCallback, useImperativeHandle, useLayoutEffect, useMemo, useRef } from 'react';
import { faceUpCards } from '../game.ts';
import { Card } from './Card.tsx';
import { useBoardFocus } from './use-board-focus.ts';
import type { CSSProperties, RefObject } from 'react';
import type { GameState } from '../game.ts';
import './board.css';

interface BoardProps {
  game: GameState;
  ref: RefObject<BoardFocus | null>;
  activate(index: number): void;
  helpId?: string;
  regionLabel?: string;
}
const NEAREST: ScrollIntoViewOptions = { block: 'nearest', inline: 'nearest' };
interface BoardStyle extends CSSProperties {
  '--grid-size': number;
}

export interface BoardFocus {
  focusRemembered(): void;
}

// Once a click or tap completes, the focused card can move fully into view.
function cardClicked(card: HTMLElement): void {
  card.scrollIntoView(NEAREST);
}

export function Board({
  game,
  ref,
  activate,
  helpId = 'board-help',
  regionLabel = 'Game board',
}: BoardProps) {
  const { size, deck, matched, selection } = game;
  const { viewport, element, focused, focusRemembered, navigate, cardFocused } =
    useBoardFocus(size);
  useImperativeHandle(ref, () => ({ focusRemembered }), [focusRemembered]);
  // A clock tick keeps both arrays, so the cards' props stay equal and no card renders again.
  const faceUp = useMemo(() => faceUpCards({ matched, selection }), [matched, selection]);
  const matchedCards = useMemo(() => new Set(matched), [matched]);
  // The game passes a new handler on each render. Cards keep one callback that calls the latest.
  const latestActivate = useRef(activate);
  useLayoutEffect(() => {
    latestActivate.current = activate;
  });
  const activateCard = useCallback((index: number) => latestActivate.current(index), []);
  const style: BoardStyle = { '--grid-size': size };
  return (
    <div
      ref={viewport}
      className="board-viewport"
      role="region"
      aria-label={regionLabel}
      aria-describedby={helpId}
    >
      <div className="board" ref={element} style={style}>
        {deck.map((face, index) => (
          <Card
            key={index}
            index={index}
            size={size}
            face={faceUp.has(index) ? face : null}
            matched={matchedCards.has(index)}
            tabIndex={focused === index ? 0 : -1}
            activate={activateCard}
            focus={cardFocused}
            clicked={cardClicked}
            navigate={navigate}
          />
        ))}
      </div>
    </div>
  );
}

import { memo } from 'react';
import { Face } from './Face.tsx';
import { describeCard } from './card-state.ts';
import type { KeyboardEvent } from 'react';
import './card.css';

interface CardProps {
  index: number;
  size: number;
  face: number | null;
  matched: boolean;
  tabIndex: number;
  activate(index: number): void;
  focus(index: number, card: HTMLElement): void;
  clicked(card: HTMLElement): void;
  navigate(event: KeyboardEvent<HTMLButtonElement>, index: number): void;
}

// Memoized, so a clock tick that changes no card renders none of them.
export const Card = memo(function Card({
  index,
  size,
  face,
  matched,
  tabIndex,
  activate,
  focus,
  clicked,
  navigate,
}: CardProps) {
  const { state, label } = describeCard(index, size, face, matched);
  // Chromium sends no click after a context menu, a long press or a touch scroll, so every click
  // activates.
  return (
    <button
      type="button"
      className={`card ${state}`}
      aria-label={label}
      aria-disabled={matched}
      tabIndex={tabIndex}
      onFocus={(event) => focus(index, event.currentTarget)}
      onKeyDown={(event) => navigate(event, index)}
      onClick={(event) => {
        activate(index);
        clicked(event.currentTarget);
      }}
    >
      {face === null ? <span className="card-back" aria-hidden="true" /> : <Face face={face} />}
      {matched && (
        <svg className="matched-mark" viewBox="0 0 12 12" aria-hidden="true" focusable="false">
          <path d="m2 6 3 3 5-6" fill="none" stroke="currentColor" strokeWidth="2" />
        </svg>
      )}
    </button>
  );
});
docs/controls.md:25:The Tournament button beside New Game opens the shared-device event screen described in Tournament mode. Its setup, leave confirmation, bracket and history are an extension to the solo controls specified here.
docs/adr-057-small-components.md:9:`Game.tsx` is the assembly point for solo play and Tournament mode. `Controls` owns solo deal actions, `GameStatus` renders progress and completion, `Board` renders and navigates cards, and `Reproduction` owns the disclosure and drafts. The Tournament feature owns its own flow and bracket. Browser session behavior lives behind `useGame`. These boundaries correspond to real responsibilities rather than a generic component taxonomy.
docs/competition-boards.md:61:The ordinary `Controls` component still renders all seven values from `GRID_SIZES` and delegates changes to `newGame`. Tournament mode uses its own stage mapping: Quarterfinal 4x4, Semifinal 6x6 and Final 8x8. The technical size catalogue and event choice remain separate.
docs/tables-policy.md:5:The solo UI has no result table. `GameStatus.tsx` displays four properties of a single game in a definition list. Tournament mode adds bracket and past-event result tables; both use captions and column headers under the policy below. Reproduction controls use forms, and the board is a CSS grid of buttons.
docs/retention-policy.md:5:Retention describes how much accepted data remains after a save. It is separate from parsing a malformed value, clearing site data in browser settings or losing a private browsing session. Solo play remembers one best move count per supported size. Tournament mode also keeps a bounded list of finished events, so a browser dump of solo bests alone cannot reconstruct tournament history.
docs/form-layout-guide.md:18:| Tournament JSON    | Labeled textarea and Export/Load buttons in a wrapped row                 | `TournamentTools.tsx`, `tournament.css` |
docs/competition-overview.md:9:Neon Pairs supports solo play and Tournament mode. `src/game/Game.tsx` keeps the solo session mounted while the separate `src/game/tournament/` feature owns tournament participants, bracket progression, exchange validation and history. Both modes reuse the same card board and game rules, while tournament completions stay outside solo preferences.
docs/competition-overview.md:11:The feature remains a local social activity, not a remote ranking service. The detailed pages identify bracket rules, deal identity, result comparison and saved-result boundaries; Tournament mode describes the player journey and JSON format.
docs/competition-overview.md:13:The existing specification is version 2.2 and describes the solo browser memory game, its reproducibility tools and its browser session. Tournament mode extends that product with a local competition flow. The additional decisions for this scope live in the linked competition pages and Tournament mode guide; this overview introduces their purpose without reproducing them.
docs/acceptance.md:5:Status: solo game spec version 2.2, with Tournament mode acceptance below.
docs/acceptance.md:40:Start four-player and eight-player events with distinct names. Check entry-order pairings, round names and stage board sizes. For a match, complete the first game and check Next turn, then complete the second game on the same board code and check the move-first result, time tie-break and seed tie-break. Advance through the bracket and check the champion. Leave an unfinished event and confirm the solo game returns without changing its bests or saved size.
docs/acceptance.md:42:Export and load a setup draft, an in-progress turn and a finished tournament JSON value. Reject malformed values and unknown fields without replacing the current tournament or draft. Finish an event, reload, open Tournament and inspect Past tournaments. Check the newest-ten retention and the storage-unavailable message.
docs/error-display-guide.md:77:Tournament setup validates the normalized names on Start tournament. A rejected attempt leaves all eight drafts editable and keeps the Tournament screen open. The shared Tournament status is the single polite live region on that screen; invalid name fields reference it with `aria-describedby`. JSON load validates before replacing the setup draft or event, keeps the text available for correction, and publishes its outcome through that same status region. A valid load that would replace an active event asks for confirmation; an invalid value reports its error without pausing the event. The visible storage warning is rendered beside Past tournaments.
docs/data-exchange-policy.md:5:The game has three established reproducibility formats with deliberately different jobs. A board code identifies a starting deal. A snapshot describes a position on that deal. A replay describes activations on a logical timeline and produces a position when evaluated. Tournament mode adds a separate `neon-pairs/tournament` export for bracket participants, deals and results. Choosing the smallest useful format keeps a report understandable: a wrong shuffle needs a code, a wrong revealed state needs a snapshot, a timeout ordering problem usually needs a replay, and a tournament record needs its tournament JSON.
docs/data-exchange-policy.md:11:The current snapshot and replay formats are JSON objects with numeric `version: 1`. The board code is a string whose prefix is `np1`. Their definitions predate the general policy for new JSON exports. Every new exported JSON object has a "format" of "neon-pairs/KIND", naming what it holds, and a whole-number "version", with its keys in alphabetical order at every level. Tournament JSON follows that policy; formats that already exist stay as they are. In particular, adding a discriminator to a version 1 snapshot would make it fail the existing exact-key check, and changing the board-code string into JSON would remove its usefulness in the Board code field.
docs/data-exchange-policy.md:39:Board codes, snapshots and replays do not contain a browser storage key, a saved size preference, a per-size best record, a focus location or an animation flag. Tournament JSON carries participant names, match codes and completed results, but no storage key or solo preference. A loaded board's size becomes the chosen size through solo session replacement; that is a browser consequence of loading, not a separate field in the existing formats. Importing a completed snapshot does not record an import as a new solo played result.
docs/storage-failure-policy.md:5:Solo play isolates preference-storage failures from the active game. It catches errors while obtaining the browser store, reading the preference key and writing its replacement. Tournament history also catches read and write failures, keeps the current event usable in memory and reports `Progress won't be saved on this device.` beside Past tournaments.
docs/storage-failure-policy.md:13:Tournament history reports unavailable storage beside Past tournaments with `Progress won't be saved on this device.` The current in-memory event and bracket continue to work when the read or write fails.
docs/interface-review-checklist.md:16:Tournament mode now has a name editor and bracket/history result tables; the solo game still has no dialog. Review the Tournament-specific behavior against its own implementation and the policies linked below.
docs/competition-scores.md:44:Both behaviors remain correct in the solo context. Tournament mode avoids them by using `createGame`, `activateCard` and its own clock through `src/game/tournament/` and `src/game/session/use-tournament-clock.ts`. It does not call `replaceGame` or `activateSession` for tournament turns.
docs/competition-scores.md:50:`useGame` reads preferences at initialization and calls `useSavedPreferences(store, session.preferences)`. That hook has an effect that invokes `writePreferences` whenever the preference object or store dependency changes. Tournament mode leaves those preferences untouched and writes only completed tournament records through its separate feature store.
docs/persistence-overview.md:5:Solo play uses `neon-pairs.preferences.v1` for the selected board size and per-size best moves. Tournament mode uses a separate `np3:tournaments` collection for finished events. Neither key stores an active game. Reloading solo play creates a fresh deal; finished tournament records remain available in Past tournaments.
docs/persistence-overview.md:19:See Preferences store for the exact validation and React effect. Tournament mode and Persistence envelope describe the tournament collection. Best score records covers the gameplay meaning of the solo numbers rather than the browser mechanism that holds them.
docs/screen-reader-notes.md:67:## Tournament mode
docs/screen-reader-notes.md:71:During an event, the shared status region says `Now playing: NAME` and publishes pair results. The Board is a named region with its own help text. Start turn begins play, Next turn hands the same deal to the other player, and Next match advances the bracket. Bracket tables have captions and column headers for Player, Moves, Time and Winner. At the end, the status says `Champion: NAME` and Back to game returns to solo play.
docs/screen-reader-notes.md:73:Leave tournament opens a native dialog. Keep playing receives focus; Escape closes the dialog and returns focus to the Leave tournament action. Loading valid JSON over an active event uses the same confirmation and returns focus to Load tournament when canceled. The Tournament screen also has labeled JSON tools and a Past tournaments table.
docs/tournament-mode.md:1:# Tournament mode
docs/tournament-mode.md:3:Tournament mode is a shared-device knockout event. It keeps participant, match and result data outside ordinary solo preferences while reusing the existing board rules and active clock.
docs/tournament-mode.md:11:Quarterfinals use 4x4 boards, Semifinals use 6x6 boards and Finals use 8x8 boards. Every match receives a unique full board code within the event. Both players in a match start fresh games from that same code, one after the other. The Start turn action begins each attempt; Next turn hands the same deal to the other player. Next match moves to the following bracket match after both results exist. Leave tournament asks for confirmation before discarding an unfinished event and pauses active time until the choice is made.
docs/tournament-mode.md:21:## Tournament JSON
docs/tournament-mode.md:23:The Tournament JSON field accepts a versioned `neon-pairs/tournament` object. Export writes alphabetized keys and includes the bracket, deal codes, completed results and an in-progress game snapshot when there is one. Exporting a setup screen preserves the selected player count and name drafts. Loading validates the complete value before replacing the tournament or setup. A valid load that would replace an active event asks for confirmation first. Unknown fields show `Unknown field: NAME.`; other rejected values show `Invalid tournament.`. A loaded in-progress turn waits for Start turn before active time or card actions resume.
docs/tournament-mode.md:25:The export is copyable text. It uses no clipboard API or network service. Tournament JSON is separate from board codes, game snapshots and browser storage.
docs/tournament-mode.md:27:## Past tournaments and storage
docs/tournament-mode.md:29:Finished tournaments are added to Past tournaments with their players, champion and match count, and remain there after reload. The newest 10 records are retained. They use the feature envelope `{ "v": 3, "items": [...] }` at `np3:tournaments`; the existing preferences key stays unchanged. Active tournament progress remains in memory and is not saved to browser storage; Export puts JSON in the field for manual transfer. If browser storage is unavailable, the current event still works and the screen says `Progress won't be saved on this device.`
docs/competition-research.md:9:The working setup was deliberately modest: one browser game, people seated close enough to see the screen and paper notes beside the device. At the time of this playtest, event sketches were discussed on paper because the game had no participant entry or bracket controller. Tournament mode now supplies those features alongside the ordinary card play and reproduction tools.
docs/architecture.md:39:- A07 - `Game.tsx` composes solo play or Tournament mode. Keep board navigation in `src/game/board`, controls in `src/game/controls`, solo session behavior in `src/game/session` and tournament behavior in `src/game/tournament`. Keep each component's props and styles beside it.
docs/text-entry-policy.md:5:Neon Pairs asks for player names in Tournament mode as well as board-code and snapshot text in solo play. Tournament setup keeps raw editing drafts in controlled fields, then normalizes accepted names before they enter the event model. This policy describes that name boundary; it does not apply to reproduction text.
docs/competition-deals.md:43:Tournament mode allocates all match codes at event start and keeps them with the bracket. This makes every match deal reproducible before play reaches it.
docs/competition-deals.md:57:During an investigation, a full board code is more precise than “the small board” or a seed copied without its size. A snapshot can add the state at the moment of interest. A replay can add timed actions. Tournament JSON carries bracket participants and results in addition to per-match codes; it does not authenticate who played.
docs/competition-pairing.md:5:Pairing connects a group of people to an event structure. Tournament mode stores participants and bracket results under `src/game/tournament/`; the card engine remains unaware of player identity. Choosing a board, recording a finished attempt and interpreting a tied result remain separate decisions.
docs/adr-041-name-limits.md:11:That choice belonged to an earlier interface design discussion. Tournament mode now has separate player-name fields with the Unicode code-point limit in Name length policy. Solo text fields remain a board code and snapshot JSON, with format-specific limits.
docs/README.md:5:Status: solo game spec version 2.2, with Tournament mode documented as an extension.
docs/README.md:11:Choose a size, then reveal a card and find its partner. Matches stay face up. A miss closes both cards after 800 active milliseconds. Finding every pair completes the game with your moves and time. New Game gives you another deal. Restart repeats the current deal. Tournament mode lets four or eight players take turns on the same deals in a knockout bracket. Full details are in Rules and Tournament mode.
docs/focus-policy.md:11:A screen replacement has a different orientation problem from resetting a deck. When Tournament replaces the solo controls, focus moves to its h2, which has `tabindex="-1"`. This gives the new screen a programmatic landing place without adding that heading to ordinary Tab traversal. Entering the next game state can then focus Start turn or the finished screen's Back to game action.

